from pathlib import Path
from datetime import datetime, timezone
import hashlib,json
W=Path.cwd();S=W/'.temp/w05-buffer-parts-v1';R=S/'review';B=W/'reports/all_unmatched_20261107/worker-05'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def osh(o):return hashlib.sha256(json.dumps(o,sort_keys=True,separators=(',',':'),ensure_ascii=False).encode()).hexdigest()
def read(p):return json.loads(p.read_text())
def bind(p):return {'path':str(p.relative_to(W)),'sha256':sha(p)}
oldD={d['case_id']:d for d in read(B/'tellurium-polypeptone-v1/core/decisions.json')['decisions']}
oldP={p['proposal_id']:p for p in read(B/'tellurium-polypeptone-v1/core/proposals.json')['proposals']}
pc={p['proposal_id']:p for p in read(R/'independent-payload-checks-v1.json')['payload_checks']}
inputs=[];cases=[];payloads=[];ev=[];manifestchecks=[]
case_text={
'hepes':'The complete decision for two source contexts correctly retains 1 M HEPES-KOH as a nominal whole stock used at 20 ml in each receiving recipe. NBRC1221 medium pH7.14 and NBRC1474 medium pH9.0 do not establish stock pH. The full primary recipes do not enumerate stock material inputs. Both exact current candidates already omit the unsupported moiety/species components and paired assertion. Added evidence and chronology are source-qualified, while the conditional family decision, all raw occurrence IDs, prior negative/owner/export holds and historical reviews remain intact.',
'tris':'The complete 16-occurrence decision preserves its established split and all historical evidence. Fresh scientific scope covers the eight stock routes: DSMZ394/1137 specify 1 M pH7.5 with 20/5 ml receiving doses; JCM1061 specifies 0.5 M pH8.0 with 100 ml dose. These are positive nominal stock specifications. No preparation inputs, solvent, free HCl or moiety/species material list are established. Both selected stock payloads already omit the unsupported components and paired assertion; the seven dry-reagent contexts and one final-medium context remain unchanged with prior attribution, without new approval from this stock review.'}
payload_text={
'CHEM-C1193-HEPES-1221':'Complete NBRC1221 candidate preserves the whole 1 M HEPES-KOH name, source URL, LLM interpretation and two authentic historical events. Neither material component slot is present. The source receiving pH7.14, water and other nested recipes have not been imported as stock properties. Historical local identity is conditional, not a claim of distinctness from NBRC1474.',
'CHEM-C1193-HEPES-1474':'Complete NBRC1474 candidate preserves the whole 1 M HEPES-KOH name, source URL, LLM interpretation and two authentic historical events. Neither material component slot is present. Receiving pH9.0 is correctly kept separate from unknown stock pH. Missing formulation facts do not prove equality or difference from NBRC1221; no owner winner or co-installation is approved.',
'CHEM-C1193-DSMZ_394_1137-Tris':'Complete stock candidate retains the source-defined nominal 1 M Tris-HCl pH7.5 preparation and all six occurrence routes. Both material component slots are absent; the stock is not mapped to dry hydrochloride or free-base species. DSMZ394 and1137 support the same bounded nominal strength/pH despite different receiving doses, without proving unknown full formulation details equal. Original identity, evidence, source-specific constraints and history are unchanged.',
'CHEM-C1193-JCM_1061-Tris':'Complete stock candidate retains the explicit 0.5 M Tris-HCl solution pH8.0 and both JCM1061 routes. Both material component slots are absent. Source water/final1L instructions describe the receiving medium, not the stock. No frozen100G_PER_L or990.099percent corruption is adopted, no molecular salt/base split is invented, and all original identity, evidence and history are unchanged.'}
for lane in ['hepes','tris']:
 L=S/lane;m=read(L/'MANIFEST.json');members=m.get('files',m.get('members',[]))
 for x in members:assert sha(L/x['path'])==x['sha256']
 manifestchecks.append({'lane':lane,'manifest':bind(L/'MANIFEST.json'),'members_rehashed':len(members),'result':'PASS'})
 for n in ['decisions.json','proposals.json','evidence.json']:inputs.append(bind(L/n))
 ds=read(L/'decisions.json')['decisions'];ps=read(L/'proposals.json')['proposals'];es=read(L/'evidence.json')['evidence']
 for d in ds:
  before=oldD[d['case_id']];changed=sorted(k for k in set(before)|set(d) if before.get(k)!=d.get(k))
  assert changed==['buffer_parts_reassessment','evidence_ids','issue_refs']
  assert all(d[k]==before[k] for k in ['source','occurrence_ids','preserved_source_holds','proposal_ids','reasoning','applicability','independent_review'])
  cases.append({'case_id':d['case_id'],'selected_decision_object_sha256':osh(d),'predecessor_decision_object_sha256':osh(before),'source_author':'/root/buffer_'+lane,'reviewer':'/root/final_skeptical','changed_fields':changed,'occurrence_ids':d['occurrence_ids'],'assessment':case_text[lane],'outcome':'pass_with_limitations','limitation':'Current nominal stock representation and bounded partonomy only; no new whole-owner, role or export admission.'})
 for p in ps:
  assert p==oldP[p['proposal_id']]
  c=pc[p['proposal_id']]
  payloads.append({'proposal_id':p['proposal_id'],'after_capture':p['after_capture'],'selected_proposal_object_sha256':osh(p),'reviewer':'/root/final_skeptical','primary_reassessment_author':'/root/buffer_'+lane,'payload_author':'/root/chemicals_research, historical correction preserved','assessment':payload_text[p['proposal_id']],'outcome':'pass_with_limitations','applies_to_occurrence_ids':p['applies_to_occurrence_ids'],'complete_payload_reviewed':True,'payload_and_proposal_unchanged_from_base':True,'field_assessments':{'identity':'Whole nominal stock identity retained; no solute identity substitution. HEPES family owner choice remains conditional.','material_partonomy':'components and component_assertion both absent; unsupported historical moieties/species are preserved only in immutable old payload/finding.','strength_pH_and_source':'Supported source strengths/pH retained; final-medium pH and water remain separate.','mapping_evidence':'Current LLM_SUGGESTION is honest agent interpretation; no human claim or enum rewrite in this supplement.','history':'Exact prior history preserved with no new no-op event. Recorded private correction predates filing; filing precedes first publication.','other_fields':'All selected payload fields are identical to base0bac and first corrected publication5156; no source, role, count or negative-object change.'},'native_check':{'capture':bind(R/'independent-payload-checks-v1.json'),'rows':c['current_native_rows'],'closed_schema_errors':c['strict_errors']},'limits':['No final owner installation or family reconciliation.','No complete formulation, solvent, titrant, component molarity or free-base/salt proportion inferred.']})
 for e in es:
  cap=e['capture'];path=cap['path'];assert path.startswith('buffer-parts-v1/')
  q=S/Path(path).relative_to('buffer-parts-v1');assert sha(q)==cap['sha256']
  ev.append({'evidence_id':e['evidence_id'],'evidence_object_sha256':osh(e),'capture':cap,'assessment':'Supported within the exact primary/source-assessment/chronology/validation scope stated; no claim of fresh retrieval or whole-owner approval. Primary capture original timestamps retained.','kind':e['kind']})
assert len(cases)==2 and len(payloads)==4 and len(ev)==13
at=datetime.now(timezone.utc).isoformat()
receipt={'reviewer':'/root/final_skeptical','completed_at':at,'base_head':'0bac12cabfd1f67f212631d8eef9aa46379f6b41','scope':'Bounded buffer component withdrawal successor: two complete source decisions, four complete already-corrected payloads, five complete primary recipes; additive source/evidence/chronology only. This is a completed subreview of the expanded consolidated successor, not its final assembled approval.','verdict':'pass_with_limitations','scientific_review':True,'source_authors':['/root/buffer_hepes','/root/buffer_tris'],'inputs':inputs,'manifest_checks':manifestchecks,'case_reviews':cases,'payload_reviews':payloads,'new_evidence_reviews':ev,'independent_primary_assessment':bind(R/'independent-primary-assessment-v1.json'),'independent_native_and_history_check':bind(R/'independent-payload-checks-v1.json'),'independent_html_read':bind(R/'independent-html-read-v1.json'),'visual_pdf_reads':[bind(R/'dsm394-page1.png'),bind(R/'dsm1137-page1.png')],'finding_dispositions':[{'finding_id':'W05-FINAL-CHEM-NEW-02','disposition':'resolved_in_exact_selected_partonomy_scope','affected_proposal_ids':['CHEM-C1193-HEPES-1221','CHEM-C1193-HEPES-1474'],'reason':'Both exact current payloads omit unsupported components and paired assertion. Source-defined whole-stock facts remain; family-owner decision is excluded.'},{'finding_id':'W05-FINAL-CHEM-NEW-03','disposition':'resolved_in_exact_selected_partonomy_scope','affected_proposal_ids':['CHEM-C1193-DSMZ_394_1137-Tris','CHEM-C1193-JCM_1061-Tris'],'reason':'Both exact current payloads omit unsupported material components and paired assertion. Whole-stock strength/pH and all eight stock routes preserved; solid-salt grading excluded.'}],'new_findings':[],'chronology_review':'Both authors accurately distinguish recorded private correction07:40:53, coordinator triage07:43:20, issue filing07:43:24, first commit08:25:04 and remote receipt08:25:25. Original finding has no standalone timestamp; no missing delivery time or filing-before-private-fix claim is manufactured.','actual_read_scope':{'full_primary_documents':5,'full_current_payloads':4,'full_original_payloads':4,'full_current_cases':2,'frozen_raw_occurrence_objects':18,'fresh_stock_occurrence_science':10,'other_tris_occurrences':'Eight retained with exact prior attribution, not reapproved by this bounded stock review.','frozen_recipe_scope':'Both complete HEPES recipe texts read; all ten stock occurrence nodes/source routes checked against complete frozen case objects. Some bulk frozen Tris-recipe output was truncated; no claim of a new independent full-text reading of every frozen Tris recipe is made. Primary DSMZ394/1137 and JCM1061 complete recipes were independently read.'},'limitations':['No maintained record changes, new YAML/proposal edit, gate change, owner union or export approval.','Root full-candidate accounting/overlay and native saved review remain separate future checks of the consolidated successor.','Original historical role/alias/other-source claims outside stock partonomy retain prior scientific attribution, not approval transfer.']}
f=R/'buffer-review-v1.json';assert not f.exists();f.write_text(json.dumps(receipt,indent=2,ensure_ascii=False)+'\n');print(f,sha(f))
